    std::vector<std::pair<double, double>> poly_ccw = {
        {lat0 - d_lat, lon0 - d_lon}, // SW
        {lat0 + d_lat, lon0 - d_lon}, // NW
        {lat0 + d_lat, lon0 + d_lon}, // NE
        {lat0 - d_lat, lon0 + d_lon}  // SE
