#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <assert.h>

#define PERIPH_BASE_ADDR 0x40001000U

#define REG_CTRL      0x00U
#define REG_STATUS    0x04U
#define REG_DATA      0x08U
#define REG_IRQ_MASK  0x0CU

#define CTRL_ENABLE_BIT        (1U << 0)
#define CTRL_IRQ_EN_BIT        (1U << 1)
#define CTRL_DMA_EN_BIT        (1U << 2)
#define CTRL_SOFT_RESET_BIT    (1U << 31)

#define STATUS_DONE_BIT        (1U << 0)
#define STATUS_ERROR_BIT       (1U << 1)
#define STATUS_BUSY_BIT        (1U << 2)
#define STATUS_FIFO_FULL_BIT   (1U << 3)
#define STATUS_FIFO_EMPTY_BIT  (1U << 4)
#define STATUS_IRQ_PENDING_BIT (1U << 31)

#define IRQ_MASK_DONE_BIT      (1U << 0)
#define IRQ_MASK_ERROR_BIT     (1U << 1)
#define IRQ_MASK_FIFO_THRESH   (1U << 2)

#define MAX_POLL_CYCLES 16U

typedef struct {
    volatile uint32_t ctrl;
    volatile uint32_t status;
    volatile uint32_t data;
    volatile uint32_t irq_mask;
} peripheral_regs_t;

static inline peripheral_regs_t *const get_periph(void) {
    return (peripheral_regs_t *const)PERIPH_BASE_ADDR;
}

static inline void dsb_sy(void) {
    __asm__ volatile ("dsb sy" ::: "memory");
}

static inline void isb_sy(void) {
    __asm__ volatile ("isb sy" ::: "memory");
}

static inline uint32_t reg_read(volatile const uint32_t *const reg) {
    assert(reg != NULL);
    uint32_t val = *reg;
    dsb_sy();
    return val;
}

static inline void reg_write(volatile uint32_t *const reg, uint32_t val) {
    assert(reg != NULL);
    dsb_sy();
    *reg = val;
    dsb_sy();
}

static inline void reg_set_bits(volatile uint32_t *const reg, uint32_t mask) {
    assert(reg != NULL);
    dsb_sy();
    *reg |= mask;
    dsb_sy();
}

static inline void reg_clear_bits(volatile uint32_t *const reg, uint32_t mask) {
    assert(reg != NULL);
    dsb_sy();
    *reg &= ~mask;
    dsb_sy();
}

bool periph_init(void) {
    peripheral_regs_t *const periph = get_periph();
    assert(periph != NULL);

    reg_write(&periph->ctrl, CTRL_SOFT_RESET_BIT);
    for (uint32_t i = 0U; i < MAX_POLL_CYCLES; ++i) {
        if ((reg_read(&periph->ctrl) & CTRL_SOFT_RESET_BIT) == 0U) {
            break;
        }
    }
    if (reg_read(&periph->ctrl) & CTRL_SOFT_RESET_BIT) {
        return false;
    }

    reg_write(&periph->irq_mask, 0U);
    reg_write(&periph->status, 0xFFFFFFFFU);
    dsb_sy();
    isb_sy();
    return true;
}

void periph_enable(bool enable) {
    peripheral_regs_t *const periph = get_periph();
    if (enable) {
        reg_set_bits(&periph->ctrl, CTRL_ENABLE_BIT);
    } else {
        reg_clear_bits(&periph->ctrl, CTRL_ENABLE_BIT);
    }
}

void periph_irq_enable(uint32_t mask) {
    peripheral_regs_t *const periph = get_periph();
    reg_write(&periph->irq_mask, mask & (IRQ_MASK_DONE_BIT | IRQ_MASK_ERROR_BIT | IRQ_MASK_FIFO_THRESH));
}

uint32_t periph_status_read(void) {
    peripheral_regs_t *const periph = get_periph();
    return reg_read(&periph->status);
}

void periph_status_clear(uint32_t mask) {
    peripheral_regs_t *const periph = get_periph();
    reg_write(&periph->status, mask & (STATUS_DONE_BIT | STATUS_ERROR_BIT | STATUS_IRQ_PENDING_BIT));
}

bool periph_wait_done(uint32_t timeout_cycles) {
    peripheral_regs_t *const periph = get_periph();
    uint32_t cycles = (timeout_cycles > MAX_POLL_CYCLES) ? MAX_POLL_CYCLES : timeout_cycles;

    for (uint32_t i = 0U; i < cycles; ++i) {
        uint32_t status = reg_read(&periph->status);
        if (status & STATUS_DONE_BIT) {
            reg_write(&periph->status, STATUS_DONE_BIT);
            return true;
        }
        if (status & STATUS_ERROR_BIT) {
            reg_write(&periph->status, STATUS_ERROR_BIT);
            return false;
        }
    }
    return false;
}

bool periph_write_data(uint32_t data) {
    peripheral_regs_t *const periph = get_periph();

    for (uint32_t i = 0U; i < MAX_POLL_CYCLES; ++i) {
        if ((reg_read(&periph->status) & STATUS_FIFO_FULL_BIT) == 0U) {
            reg_write(&periph->data, data);
            return true;
        }
    }
    return false;
}

bool periph_read_data(uint32_t *const out_data) {
    assert(out_data != NULL);
    peripheral_regs_t *const periph = get_periph();

    for (uint32_t i = 0U; i < MAX_POLL_CYCLES; ++i) {
        if ((reg_read(&periph->status) & STATUS_FIFO_EMPTY_BIT) == 0U) {
            *out_data = reg_read(&periph->data);
            return true;
        }
    }
    return false;
}

void periph_soft_reset(void) {
    peripheral_regs_t *const periph = get_periph();
    reg_write(&periph->ctrl, CTRL_SOFT_RESET_BIT);
    dsb_sy();
    isb_sy();
}
