// Simple benchmark & invariant verification
// ------------------------------------------------------------
int main() {
    constexpr size_t N = 10000;               // number of intervals
    constexpr int64_t MAX_TIME = 1'000'000;   // timeline range

    // Deterministic random generator
    std::mt19937_64 rng(0xDEADBEEF);
    std::uniform_int_distribution<int64_t> durDist(1, 1000);
    std::uniform_int_distribution<int64_t> startDist(0, MAX_TIME - 1000);

    // Generate nested intervals: each interval may contain a few smaller ones
    std::vector<Interval> intervals;
    intervals.reserve(N);
    for (size_t i = 0; i < N; ++i) {
        int64_t start = startDist(rng);
        int64_t dur   = durDist(rng);
        int64_t end   = std::min(start + dur, MAX_TIME);
        intervals.push_back({start, end, static_cast<int>(i)});
    }

    // Build tree
    IntervalTree tree(intervals);

    // Verify 64‑byte alignment of node storage
    const auto& nodes = tree.getNodes();
    const void* nodePtr = nodes.data();
    assert(reinterpret_cast<uintptr_t>(nodePtr) % 64 == 0 && "Node storage not 64‑byte aligned");

    // Query verification: compare against brute‑force for random points
    std::uniform_int_distribution<int64_t> pointDist(0, MAX_TIME);
    std::vector<int> resultTree, resultBrute;
    for (int trial = 0; trial < 1000; ++trial) {
        int64_t p = pointDist(rng);
        tree.query(p, intervals, resultTree);
        resultBrute.clear();
        for (const auto& iv : intervals) {
            if (iv.start <= p && p < iv.end) resultBrute.push_back(iv.id);
        }
        std::sort(resultTree.begin(), resultTree.end());
        std::sort(resultBrute.begin(), resultBrute.end());
        assert(resultTree == resultBrute && "Query mismatch");
    }

    // Simple benchmark (no output, just ensure it runs fast)
    auto t0 = std::chrono::high_resolution_clock::now();
    for (int64_t p = 0; p < MAX_TIME; p += 123) {
        tree.query(p, intervals, resultTree);
        // Do nothing with result; just force traversal
        (void)resultTree;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = t1 - t0;
    std::cout << "Benchmark completed in " << elapsed.count() << " s\n";

    return 0;
}
