// ---------- bfloat16 emulation ----------
struct bfloat16 {
    uint16_t data;
    bfloat16() = default;
    bfloat16(uint16_t d) : data(d) {}
    explicit bfloat16(float f) {
        uint32_t u;
        std::memcpy(&u, &f, sizeof(float));
        data = static_cast<uint16_t>(u >> 16);
    }
    operator float() const {
        uint32_t u = static_cast<uint32_t>(data) << 16;
        float f;
        std::memcpy(&f, &u, sizeof(float));
        return f;
    }
    bool operator==(const bfloat16& other) const { return data == other.data; }
